<?php
namespace qqworld_collector\module\collect_filter; class remove_emoji extends filter { public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $item = preg_replace('/[\x{1F600}-\x{1F64F}\x{1F300}-\x{1F5FF}\x{1F680}-\x{1F6FF}\x{2600}-\x{26FF}\x{2700}-\x{27BF}]/u', '', $item); return $item; } } ?>